import{_ as a,o,c as n,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/DATA-LIST-FIXED-Examples.md","filePath":"manual-zh/DATA-LIST-FIXED-Examples.md","lastUpdated":1785684581000}'),A={name:"manual-zh/DATA-LIST-FIXED-Examples.md"};function p(r,e,l,d,I,s){return o(),n("div",null,[...e[0]||(e[0]=[t('<h4 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h4><ol><li><p>DATA LIST TABLE /NAME 1-10 (A) INFO1 TO INFO3 12-17 (1).</p><pre><code>BEGIN DATA.\nJohn Smith 102311\nBob Arnold 122015\nBill Yates  918 6\nEND DATA.\n</code></pre></li></ol><p>定义以下变量：</p><pre><code> * `NAME`，一个 10 字符宽的字符串变量，位于第 1 至 10 列。\n * `INFO1`，一个数值变量，位于第 12 至 13 列。\n * `INFO2`，一个数值变量，位于第 14 至 15 列。\n * `INFO3`，一个数值变量，位于第 16 至 17 列。\n</code></pre><p><code>BEGIN DATA</code>/<code>END DATA</code> 命令定义了三个个案：</p><pre><code>Case   NAME         INFO1   INFO2   INFO3\n   1   John Smith     10      23      11\n   2   Bob Arnold     12      20      15\n   3   Bill Yates      9      18       6\n</code></pre><p><code>TABLE</code> 关键字使 PSPP 打印出描述所定义四个变量的表。</p><ol start="2"><li>DATA LIST FILE=&quot;survey.dat&quot; /ID 1-5 NAME 7-36 (A) SURNAME 38-67 (A) MINITIAL 69 (A) /Q01 TO Q50 7-56 /.</li></ol><p>定义以下变量：</p><pre><code> * `ID`，一个数值变量，位于第一个记录的第 1-5 列。\n * `NAME`，一个 30 字符的字符串变量，位于第一个记录的第 7-36 列。\n * `SURNAME`，一个 30 字符的字符串变量，位于第一个记录的第 38-67 列。\n * `MINITIAL`，一个 1 字符的字符串变量，位于第一个记录的第 69 列。\n * 五十个变量 `Q01`、`Q02`、`Q03`、…、`Q49`、`Q50`，均为数值型，`Q01` 在第 7 列，`Q02` 在第 8 列，…，`Q49` 在第 55 列，`Q50` 在第 56 列，全部位于第二个记录。\n</code></pre><p>个案之间以一个空记录分隔。</p><p>数据从当前目录下的 survey.dat 文件中读取。</p>',12)])])}const E=a(A,[["render",p]]);export{T as __pageData,E as default};
